<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$current=$definitions[$tab];?>
<div class="space-y-5"><div><h1 class="text-3xl font-bold">Ajustes generales</h1><p class="text-slate-400">Configuración central de OrionX. Los secretos guardados nunca se vuelven a mostrar.</p></div><nav class="flex flex-wrap gap-2 bg-slate-900 border border-slate-800 rounded-xl p-2"><?php foreach($definitions as $key=>$definition):?><a href="/settings?tab=<?=$key?>" class="px-4 py-2 rounded <?=$tab===$key?'bg-cyan-700':'hover:bg-slate-800'?>"><?=$e($definition['label'])?></a><?php endforeach?></nav><form method="post" action="/settings" class="space-y-5"><?=$csrf->field()?><input type="hidden" name="tab" value="<?=$e($tab)?>"><?php foreach($current['sections'] as $section=>$fields):?><section class="bg-slate-900 border border-slate-800 rounded-xl p-5"><h2 class="text-xl font-bold mb-4"><?=$e($section)?></h2><div class="grid md:grid-cols-2 xl:grid-cols-3 gap-4"><?php foreach($fields as $f):$value=array_key_exists($f['key'],$values)?$values[$f['key']]:$f['default'];$disabled=($f['enabled']??true)===false;?><label class="<?=$f['type']==='checkbox'?'flex items-center justify-between bg-slate-800/60 p-3 rounded':'space-y-1'?> <?=$disabled?'opacity-50':''?>"><span><?=$e($f['label'])?><?php if($disabled):?> <small>(deshabilitado por seguridad)</small><?php endif?></span><?php if($f['type']==='checkbox'):?><input type="checkbox" name="<?=$e($f['key'])?>" value="1" <?=$value?'checked':''?> <?=$disabled?'disabled':''?>><?php elseif($f['type']==='number'):?><input type="number" name="<?=$e($f['key'])?>" value="<?=$e($value)?>" min="<?=$f['min']?>" max="<?=$f['max']?>" class="w-full bg-slate-800 p-2 rounded" <?=$disabled?'disabled':''?>><?php elseif($f['type']==='select'):?><select name="<?=$e($f['key'])?>" class="w-full bg-slate-800 p-2 rounded"><?php foreach($f['options'] as $option=>$label):?><option value="<?=$e($option)?>" <?=$value===$option?'selected':''?>><?=$e($label)?></option><?php endforeach?></select><?php elseif($f['type']==='textarea'):?><textarea name="<?=$e($f['key'])?>" rows="3" class="w-full bg-slate-800 p-2 rounded" placeholder="Uno por línea o JSON, según el campo"><?=$e($value)?></textarea><?php elseif($f['type']==='password'):?><input type="password" name="<?=$e($f['key'])?>" value="" autocomplete="new-password" placeholder="Dejar vacío para conservar el secreto actual" class="w-full bg-slate-800 p-2 rounded"><?php else:?><input type="text" name="<?=$e($f['key'])?>" value="<?=$e($value)?>" class="w-full bg-slate-800 p-2 rounded" <?=$disabled?'disabled':''?>><?php endif?></label><?php endforeach?></div></section><?php endforeach?><div class="sticky bottom-4 flex justify-end"><button class="bg-emerald-600 shadow-xl px-6 py-3 rounded-lg font-bold">Guardar <?=$e($current['label'])?></button></div></form></div>
